/**
 * AI Engineer Practice Guide — service worker.
 *
 * Hand-written rather than generated by `@serwist/next`, because what this app
 * needs is four routing rules over content that is already static. A build
 * plugin would add a dependency, a webpack/turbopack integration and a
 * generated precache manifest to express the same four rules, in a project
 * whose whole point is a thin dependency tree.
 *
 * The one thing a precache manifest buys — knowing this build's hashed asset
 * URLs up front — is recovered by `warm()` below: the page hands the worker
 * the exact URLs it just loaded, so the very first visit is enough to make the
 * next launch work offline.
 *
 * Strategies, and why each one:
 *
 *   /_next/static/*   cache-first. Content-addressed and immutable, so a hit
 *                     is always correct and a new build simply asks for new
 *                     URLs. This is what makes an offline launch instant.
 *   /icons/*          cache-first. Same reasoning, no hash but never changes.
 *   navigations, RSC  stale-while-revalidate. The question banks, decks and
 *                     cheat sheets are effectively static, and this is the
 *                     content that has to survive a commute with no signal.
 *                     Revalidating in the background is also what stops the
 *                     classic "stuck on an old build forever" bug — no HTML is
 *                     ever served cache-first.
 *   /api/feed/*       network-first with a cache fallback. Feed data is
 *                     time-sensitive and already carries a 3-hour HTTP cache;
 *                     serving it from the SW cache first would show stale news
 *                     to someone who is online. On failure the last response
 *                     is returned so the Feed degrades instead of breaking.
 *
 * Everything else is passed straight through: non-GET requests, cross-origin
 * requests (notably the two publisher image CDNs, which have their own
 * caching), and `/_next/image`, which proxies those same CDNs.
 *
 * Bump VERSION when the cache layout or a strategy changes. It does not need
 * bumping per deploy: nothing that can go stale is served cache-first.
 */

const VERSION = 'v1'
const CACHE_PREFIX = 'aeg-'

const CACHES = {
  /** Precached non-HTML: the manifest and the icon set. */
  shell: `${CACHE_PREFIX}shell-${VERSION}`,
  /** Immutable build output. */
  static: `${CACHE_PREFIX}static-${VERSION}`,
  /** Documents and RSC payloads. */
  pages: `${CACHE_PREFIX}pages-${VERSION}`,
  /** The last successful feed response per endpoint. */
  feed: `${CACHE_PREFIX}feed-${VERSION}`,
}

const OFFLINE_URL = '/offline'
const START_URL = '/today'

/** Fetched at install so a cold offline launch has something to open. */
const PRECACHE_PAGES = [START_URL, OFFLINE_URL]
const PRECACHE_ASSETS = [
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/icons/apple-touch-icon.png',
]

/**
 * The routing table, as a pure function so it can be asserted directly.
 *
 * Takes a plain descriptor rather than a `Request` so the unit test does not
 * have to build one; the fetch handler below does the unwrapping.
 *
 * @param {{ method: string, mode: string, url: string, rsc: boolean }} req
 * @returns {{ strategy: string, cache: string } | null} null means "do not
 *   intercept" — the request goes to the network as if no worker existed.
 */
function classify(req) {
  if (req.method !== 'GET') return null

  let url
  try {
    url = new URL(req.url)
  } catch {
    return null
  }
  if (url.origin !== self.location.origin) return null

  const path = url.pathname

  if (path.startsWith('/api/feed/')) return { strategy: 'network-first', cache: CACHES.feed }
  // No other API route exists today; if one lands, it opts in deliberately.
  if (path.startsWith('/api/')) return null
  // Optimised publisher art. Same origin, but the bytes come from a CDN that
  // already caches them and they are large — not our cache's job.
  if (path.startsWith('/_next/image')) return null

  if (path.startsWith('/_next/static/')) return { strategy: 'cache-first', cache: CACHES.static }
  if (path.startsWith('/icons/')) return { strategy: 'cache-first', cache: CACHES.shell }

  if (req.mode === 'navigate') return { strategy: 'stale-while-revalidate', cache: CACHES.pages }
  if (req.rsc) return { strategy: 'stale-while-revalidate', cache: CACHES.pages }

  if (path === '/manifest.webmanifest' || path === '/favicon.ico') {
    return { strategy: 'stale-while-revalidate', cache: CACHES.shell }
  }

  return null
}

/**
 * The cache key for a request.
 *
 * A string, not the `Request`, on purpose: Next sends `Vary: RSC, ...` on
 * documents, and a stored `Request` would make cache matching depend on
 * header negotiation that differs between a prefetch and a reload. The RSC
 * payload URL already carries its own `_rsc` query param, so document and
 * payload never collide.
 */
function cacheKey(url) {
  return url.pathname + url.search
}

/** Only same-origin, complete, successful responses are worth storing. */
function isStorable(response) {
  return Boolean(response) && response.status === 200 && response.type === 'basic'
}

async function cacheFirst(request, key, cacheName) {
  const cache = await caches.open(cacheName)
  const hit = await cache.match(key)
  if (hit) return hit
  const response = await fetch(request)
  if (isStorable(response)) await cache.put(key, response.clone())
  return response
}

async function staleWhileRevalidate(event, request, key, cacheName) {
  const cache = await caches.open(cacheName)
  const hit = await cache.match(key)

  const revalidate = fetch(request).then(async (response) => {
    if (isStorable(response)) await cache.put(key, response.clone())
    return response
  })

  if (hit) {
    // Let the refresh finish after the cached copy has already been served.
    event.waitUntil(revalidate.catch(() => undefined))
    return hit
  }

  try {
    return await revalidate
  } catch (err) {
    if (request.mode === 'navigate') {
      const fallback = await caches.match(OFFLINE_URL)
      if (fallback) return fallback
    }
    throw err
  }
}

async function networkFirst(request, key, cacheName) {
  const cache = await caches.open(cacheName)
  try {
    const response = await fetch(request)
    if (isStorable(response)) await cache.put(key, response.clone())
    return response
  } catch (err) {
    const hit = await cache.match(key)
    if (hit) return hit
    // Nothing cached: fail exactly as the network would have, so the Feed's
    // own error state renders instead of a fabricated empty payload.
    throw err
  }
}

/**
 * Cache the build assets a page reports having loaded.
 *
 * Requests made before this worker activated were never seen by it, so a
 * first visit would otherwise leave the JS uncached and the next launch would
 * be HTML-only. The registrar posts `performance.getEntriesByType('resource')`
 * once it is in control; this stores the same-origin build output from it.
 */
async function warm(urls) {
  const cache = await caches.open(CACHES.static)
  await Promise.all(
    urls.slice(0, 200).map(async (raw) => {
      try {
        const url = new URL(raw, self.location.origin)
        if (url.origin !== self.location.origin) return
        if (!url.pathname.startsWith('/_next/static/')) return
        const key = cacheKey(url)
        if (await cache.match(key)) return
        const response = await fetch(url.href, { credentials: 'same-origin' })
        if (isStorable(response)) await cache.put(key, response)
      } catch {
        // A warm-up miss is not a failure; the asset caches on next use.
      }
    }),
  )
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      // Settled, not `addAll`: one 404 in the list would abort the whole
      // install and leave the app with no worker at all.
      const pages = await caches.open(CACHES.pages)
      const shell = await caches.open(CACHES.shell)
      await Promise.allSettled([
        ...PRECACHE_PAGES.map(async (path) => {
          const response = await fetch(path, { credentials: 'same-origin' })
          if (isStorable(response)) await pages.put(path, response)
        }),
        ...PRECACHE_ASSETS.map(async (path) => {
          const response = await fetch(path, { credentials: 'same-origin' })
          if (isStorable(response)) await shell.put(path, response)
        }),
      ])
      // Deliberate: the alternative is waiting for every tab to close, which is
      // exactly how PWAs strand people on an old build. It is safe here because
      // nothing HTML is served cache-first, so a mid-session swap cannot show
      // older content, and progress is written to localStorage synchronously,
      // so there is no in-flight state for a new worker to lose.
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set(Object.values(CACHES))
      const keys = await caches.keys()
      await Promise.all(
        keys
          .filter((key) => key.startsWith(CACHE_PREFIX) && !keep.has(key))
          .map((key) => caches.delete(key)),
      )
      // Paired with skipWaiting: take over the page that installed us, so the
      // first visit already populates the caches rather than the second.
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('message', (event) => {
  const data = event.data
  if (!data || data.type !== 'aeg:warm' || !Array.isArray(data.urls)) return
  event.waitUntil(warm(data.urls))
})

self.addEventListener('fetch', (event) => {
  const request = event.request

  // DevTools issues these while the panel is open; responding to one throws.
  if (request.cache === 'only-if-cached' && request.mode !== 'same-origin') return

  const route = classify({
    method: request.method,
    mode: request.mode,
    url: request.url,
    rsc: request.headers.get('RSC') === '1',
  })
  if (!route) return

  const key = cacheKey(new URL(request.url))

  if (route.strategy === 'cache-first') {
    event.respondWith(cacheFirst(request, key, route.cache))
  } else if (route.strategy === 'network-first') {
    event.respondWith(networkFirst(request, key, route.cache))
  } else {
    event.respondWith(staleWhileRevalidate(event, request, key, route.cache))
  }
})

// Exposed only when this file is evaluated as a module by the unit test;
// `module` is undefined in a worker, so this is a no-op in the browser.
if (typeof module !== 'undefined' && module) {
  module.exports = { classify, cacheKey, CACHES, CACHE_PREFIX, VERSION, OFFLINE_URL, START_URL, PRECACHE_PAGES, PRECACHE_ASSETS }
}
